package com.ruoyi.medical.persistence;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;
/** Explicit Writer lane. Production dependencies must be installed; no provider fallback. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.professional-runtime.section-writer-enabled",havingValue="true",matchIfMissing=false)
public class TaskSectionWriterInvocationConfiguration {
 @Bean(name="sectionWriterInvocationHttpSchema") TaskInvocationHttpSchema sectionWriterInvocationHttpSchema(FormalInvocationSchema schema)throws Exception{return new TaskInvocationHttpSchema(schema);}
 @Bean TaskSectionWriterInvocationSchema taskSectionWriterInvocationSchema()throws Exception{return new TaskSectionWriterInvocationSchema();}
 @Bean TaskSectionWriterInvocationObjects taskSectionWriterInvocationObjects(DataSource data,PermissionSchema json,FormalInvocationSchema schema,TaskSectionWriterInvocationSchema exact,DependencyManifestSchema manifests){return new TaskSectionWriterInvocationObjects(data,json,schema,exact,manifests);}
 @Bean TaskSectionWriterInvocationRecords taskSectionWriterInvocationRecords(DataSource data,TaskSectionWriterInvocationObjects objects,FormalInvocationSchema schema,PermissionSchema json,TaskSectionWriterProducerAuthority producers){return new TaskSectionWriterInvocationRecords(data,objects,schema,json,producers);}
 @Bean TaskSectionWriterInvocationContext taskSectionWriterInvocationContext(DataSource data,ModelConfigurationService models,ModelEligibilityAuthority eligibility,ResourceReadAuthority resources,SourceReadAuthority sources,TaskInvocationPackages packages,FormalInvocationSourceOriginals originals,FormalInvocationSchema schema,TaskSectionWriterInvocationSchema exact,PermissionSchema json,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,TaskSectionWriterProducerAuthority producers,TaskSectionWriterContextReads contentReads){return new TaskSectionWriterInvocationContext(data,models,eligibility,resources,sources,packages,originals,schema,exact,json,transport,producers,contentReads);}
 @Bean TaskSectionWriterInvocationService taskSectionWriterInvocationService(DataSource data,TaskSectionWriterSupervisor supervisors,TaskSectionWriterWorkerAccess workers,RunTokenAuthority tokens,TaskSectionWriterInvocationContext contexts,TaskSectionWriterInvocationRecords records,FormalInvocationReservations reservations,FormalInvocationDispatch dispatch,FormalInvocationReceiptObjects receipts,FormalInvocationSettlement settlement,FormalInvocationObjectRegistration objects,FormalProviderCaptureEvidence captures,FormalInvocationSchema schema)throws Exception{return new TaskSectionWriterInvocationService(data,supervisors,workers,tokens,contexts,records,reservations,dispatch,receipts,settlement,objects,new TaskInvocationResults(data,null,settlement,objects,captures,schema),schema);}
 @Bean TaskSectionWriterInvocationContextOrchestrator taskSectionWriterInvocationContextOrchestrator(TaskSectionWriterHostAccess hosts,TaskSectionWriterSupervisor supervisors,TaskSectionWriterInvocationContext contexts,FormalInvocationSourceOriginals originals,TaskInvocationPackages packages,FormalTokenizerRunner tokenizer,TaskSectionWriterInvocationObjects objects,@Qualifier("formalInvocationObjectTransport")RuntimeObjectTransport transport,TaskSectionWriterInvocationRecords records,TaskSectionWriterInvocationService invocations){return new TaskSectionWriterInvocationContextOrchestrator(hosts,supervisors,contexts,originals,packages,tokenizer,objects,transport,records,invocations);}
 @Bean(name="sectionWriterInvocationLocalBridge") TaskInvocationLocalBridge sectionWriterInvocationLocalBridge(org.springframework.core.env.Environment e){String p="medical.professional-runtime.section-writer-gateway.";return new TaskInvocationLocalBridge(new TaskInvocationLocalBridge.Configuration(java.nio.file.Path.of(e.getRequiredProperty(p+"executable")),e.getRequiredProperty(p+"executable-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"entrypoint")),e.getRequiredProperty(p+"entrypoint-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"package-root")),java.nio.file.Path.of(e.getRequiredProperty(p+"package-manifest")),e.getRequiredProperty(p+"package-manifest-sha256"),java.nio.file.Path.of(e.getRequiredProperty(p+"private-configuration")),java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty(p+"timeout-seconds")))));}
 @Bean TaskSectionWriterInvocationBridge taskSectionWriterInvocationBridge(TaskSectionWriterInvocationContextOrchestrator contexts,TaskSectionWriterInvocationService service,@Qualifier("sectionWriterInvocationLocalBridge")TaskInvocationLocalBridge bridge,org.springframework.core.env.Environment e)throws Exception{return new TaskSectionWriterInvocationBridge(contexts,service,bridge,java.time.Duration.ofSeconds(Long.parseLong(e.getRequiredProperty("medical.professional-runtime.section-writer-model-token-lifetime-seconds"))));}
}
